import{_ as l,a0 as p,w as a,s as d,ao as e,I as n,x as o,a1 as i,A as u}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const U=JSON.parse('{"title":"如何實現 Linux + Windows 雙系統啓動 | LCTT x X-CMD","titleTemplate":false,"description":"如何實現 Linux + Windows 雙系統啓動 | LCTT (201812) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"如何實現 Linux + Windows 雙系統啓動 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"如何實現 Linux + Windows 雙系統啓動 | LCTT (201812) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201812/20180523 How to dual-boot Linux and Windows","title":"如何實現 Linux + Windows 雙系統啓動","tag":"201812","desc":""},"relativePath":"201812/20180523 How to dual-boot Linux and Windows.md","filePath":"[post].md"}'),r={name:"201812/20180523 How to dual-boot Linux and Windows.md"};function b(w,t,f,m,x,W){const s=p("Link");return a(),d("div",null,[t[24]||(t[24]=e('<h1 id="如何實現-linux-windows-雙系統啓動" tabindex="-1">如何實現 Linux + Windows 雙系統啓動 <a class="header-anchor" href="#如何實現-linux-windows-雙系統啓動" aria-label="Permalink to “如何實現 Linux + Windows 雙系統啓動”">​</a></h1><blockquote><p>設置你的計算機根據需要啓動 Windows 10 或 Ubuntu 18.04。</p></blockquote><p><img src="https://opensource.com/sites/default/files/styles/image-full-size/public/lead-images/migration_innovation_computer_software.png?itok=VCFLtd0q" alt=""></p><p>儘管 Linux 是一個有着廣泛的硬件和軟件支持的操作系統，但事實上有時你仍需要使用 Windows，也許是因為有些不能在 Linux 下運行的重要軟件。但幸運地是，雙啓動 Windows 和 Linux 是很簡單的 —— 在這篇文章中我將會向你展示如何實現 Windows 10 + Ubuntu 18.04 雙系統啓動。</p><p>在你開始之前，確保你已經備份了你的電腦文件。雖然設置雙啓動過程不是非常複雜，但意外有可能仍會發生。所以花一點時間來備份你的重要文件以防混沌理論發揮作用。除了備份你的文件之外，考慮製作一份備份鏡像也是個不錯的選擇，雖然這不是必需的且會變成一個更高級的過程。</p><h3 id="要求" tabindex="-1">要求 <a class="header-anchor" href="#要求" aria-label="Permalink to “要求”">​</a></h3><p>為了開始，你將需要以下 5 項東西：</p><h4 id="_1、兩個-usb-閃存盤-或者-dvd-r" tabindex="-1">1、兩個 USB 閃存盤（或者 DVD-R） <a class="header-anchor" href="#_1、兩個-usb-閃存盤-或者-dvd-r" aria-label="Permalink to “1、兩個 USB 閃存盤（或者 DVD-R）”">​</a></h4><p>我推薦用 USB 閃存盤來安裝 Windows 和 Ubuntu，因為他們比 DVD 更快。這通常是毋庸置疑的， 但是創建一個可啓動的介質會抹除閃存盤上的一切東西。因此，確保閃存盤是空的或者其包含的文件是你不再需要的。</p><p>如果你的電腦不支持從 USB 啓動，你可以創建 DVD 介質來代替。不幸的是，因為電腦上的 DVD 燒錄軟件似乎各有不同，所以我無法使用這一過程。然而，如果你的 DVD 燒錄軟件有從一個 ISO 鏡像中燒錄的選項，這個選項是你需要的。</p><h4 id="_2、一份-windows-10-許可證" tabindex="-1">2、一份 Windows 10 許可證 <a class="header-anchor" href="#_2、一份-windows-10-許可證" aria-label="Permalink to “2、一份 Windows 10 許可證”">​</a></h4><p>如果你的電腦已經安裝 Windows 10，那麼許可證將會被安裝到你的電腦中，所以你不需要擔心在安裝過程中輸入它。如果你購買的是零售版，你應該擁有一個需要在安裝過程中輸入的產品密鑰。</p><h4 id="_3、windows-10-介質創建工具" tabindex="-1">3、Windows 10 介質創建工具 <a class="header-anchor" href="#_3、windows-10-介質創建工具" aria-label="Permalink to “3、Windows 10 介質創建工具”">​</a></h4>',13)),n("p",null,[t[1]||(t[1]=o("下載並運行 Windows 10 ",-1)),i(s,{href:"https://www.microsoft.com/en-us/software-download/windows10"},{default:u(()=>[...t[0]||(t[0]=[o("介質創建工具",-1)])]),_:1}),t[2]||(t[2]=o("。一旦你運行這個工具，它將會引導你完成在一個 USB 或者 DVD-R 上創建 Windows 安裝介質的所需步驟。注意：即使你已經安裝了 Windows 10，創建一個可引導的介質也是一個不錯的主意，萬一剛好系統出錯了且需要你重新安裝。",-1))]),t[25]||(t[25]=n("h4",{id:"_4、ubuntu-18-04-安裝介質",tabindex:"-1"},[o("4、Ubuntu 18.04 安裝介質 "),n("a",{class:"header-anchor",href:"#_4、ubuntu-18-04-安裝介質","aria-label":"Permalink to “4、Ubuntu 18.04 安裝介質”"},"​")],-1)),n("p",null,[t[4]||(t[4]=o("下載 ",-1)),i(s,{href:"https://www.ubuntu.com/download/desktop"},{default:u(()=>[...t[3]||(t[3]=[o("Ubuntu 18.04",-1)])]),_:1}),t[5]||(t[5]=o(" ISO 鏡像。",-1))]),t[26]||(t[26]=n("h4",{id:"_5、etcher-軟件-用於製作一個可引導-ubuntu-的-usb-驅動器",tabindex:"-1"},[o("5、Etcher 軟件（用於製作一個可引導 Ubuntu 的 USB 驅動器） "),n("a",{class:"header-anchor",href:"#_5、etcher-軟件-用於製作一個可引導-ubuntu-的-usb-驅動器","aria-label":"Permalink to “5、Etcher 軟件（用於製作一個可引導 Ubuntu 的 USB 驅動器）”"},"​")],-1)),n("p",null,[t[7]||(t[7]=o("用於為任何 Linux 發行版創建可啓動的介質的工具，我推薦 ",-1)),i(s,{href:"http://www.etcher.io"},{default:u(()=>[...t[6]||(t[6]=[o("Etcher",-1)])]),_:1}),t[8]||(t[8]=o("。Etcher 可以在三大主流操作系統（Linux、MacOS 和 Windows）上運行且不會讓你覆蓋當前操作系統的分區。",-1))]),t[27]||(t[27]=e('<p>一旦你下載完成並運行 Etcher，點擊選擇鏡像並指向你在步驟 4 中下載的 Ubuntu ISO 鏡像， 接下來，點擊驅動器以選擇你的閃存驅動器，然後點擊 “Flash!” 開始將閃存驅動器轉化為一個 Ubuntu 安裝器的過程。 （如果你正使用一個 DVD-R，使用你電腦中的 DVD 燒錄軟件來完成此過程。）</p><h3 id="安裝-windows-和-ubuntu" tabindex="-1">安裝 Windows 和 Ubuntu <a class="header-anchor" href="#安裝-windows-和-ubuntu" aria-label="Permalink to “安裝 Windows 和 Ubuntu”">​</a></h3><p>你應該準備好了，此時，你應該完成以下操作：</p><ul><li>備份你重要的文件</li><li>創建 Windows 安裝介質</li><li>創建 Ubuntu 安裝介質</li></ul><p>有兩種方法可以進行安裝。首先，如果你已經安裝了 Windows 10 ，你可以讓 Ubuntu 安裝程序調整分區大小，然後在空白區域上進行安裝。或者，如果你尚未安裝 Windows 10，你可以在安裝過程中將它（Windows）安裝在一個較小的分區上（下面我將描述如何去做）。第二種方法是首選的且出錯率較低。很有可能你不會遇到任何問題，但是手動安裝 Windows 並給它一個較小的分區，然後再安裝 Ubuntu 是最簡單的方法。</p><p>如果你的電腦上已經安裝了 Windows 10，那麼請跳過以下的 Windows 安裝説明並繼續安裝 Ubuntu。</p><h4 id="安裝-windows" tabindex="-1">安裝 Windows <a class="header-anchor" href="#安裝-windows" aria-label="Permalink to “安裝 Windows”">​</a></h4><p>將創建的 Windows 安裝介質插入你的電腦中並引導其啓動。這如何做取決於你的電腦。但大多數有一個可以按下以顯示啓動菜單的快捷鍵。例如，在戴爾的電腦上就是 F12 鍵。如果閃存盤並未作為一個選項顯示，那麼你可能需要重新啓動你的電腦。有時候，只有在啓動電腦前插入介質才能使其顯示出來。如果看到類似“請按任意鍵以從安裝介質中啓動”的信息，請按下任意一個鍵。然後你應該會看到如下的界面。選擇你的語言和鍵盤樣式，然後單擊 “Next”。</p><p><img src="https://opensource.com/sites/default/files/uploads/linux-dual-boot_01.png" alt="Windows 安裝" title="Windows setup"></p><p>點擊“現在安裝”啓動 Windows 安裝程序。</p><p><img src="https://opensource.com/sites/default/files/uploads/linux-dual-boot_02a.png" alt="現在安裝"></p><p>在下一個屏幕上，它會詢問你的產品密鑰。如果因你的電腦在出廠時已經安裝了 Windows 10 而沒有密鑰的話，請選擇“我沒有一個產品密鑰”。在安裝完成後更新該密碼後會自動激活。如果你有一個產品密鑰，輸入密鑰並單擊“下一步”。</p><p><img src="https://opensource.com/sites/default/files/uploads/linux-dual-boot_03.png" alt="輸入產品密鑰" title="Enter product key"></p><p>選擇你想要安裝的 Windows 版本。如果你有一個零售版，封面標籤（LCTT 譯註：類似於 CPU 型號的 logo 貼標）會告訴你你有什麼版本。否則，它通常在你的計算機的附帶文檔中可以找到。在大多數情況下，它要麼是 Windows 10 家庭版或者 Windows 10 專業版。大多數帶有 家庭版的電腦都有一個簡單的標籤，上面寫着“Windows 10”，而專業版則會明確標明。</p><p><img src="https://opensource.com/sites/default/files/uploads/linux-dual-boot_04.png" alt="選擇 Windows 版本" title="Select Windows version"></p><p>勾選複選框以接受許可協議，然後單擊“下一步”。</p><p><img src="https://opensource.com/sites/default/files/uploads/linux-dual-boot_05.png" alt="接受許可協議" title="Accept license terms"></p><p>在接受協議後，你有兩種可用的安裝選項。選擇第二個選項“自定義：只安裝 Windows （高級）”。</p><p><img src="https://opensource.com/sites/default/files/uploads/linux-dual-boot_06.png" alt="選擇 Windows 的安裝方式" title="Select type of Windows installation"></p><p>接下來應該會顯示你當前的硬盤配置。</p><p><img src="https://opensource.com/sites/default/files/uploads/linux-dual-boot_07.png" alt="硬盤配置" title="Hard drive configuration"></p><p>你的結果可能看起來和我的不一樣。我以前從來沒有用過這個硬盤，所以它是完全未分配的。你可能會看到你當前操作系統的一個或多個分區。選中每個分區並移除它。（LCTT 譯註：確保這些分區中沒有你需要的數據！！）</p><p>此時，你的電腦屏幕將顯示未分配的整個磁盤。創建一個新的分區以繼續安裝。</p><p><img src="https://opensource.com/sites/default/files/uploads/linux-dual-boot_08.png" alt="創建一個新分區" title="Create a new partition"></p><p>你可以看到我通過創建一個 81920MB 大小的分區（接近 160GB 的一半）將驅動器分成了一半（或者説接近一半）。給 Windows 至少 40GB，最好 64GB 或者更多。把剩下的硬盤留着不要分配，作為以後安裝 Ubuntu 的分區。</p><p>你的結果應該看起來像這樣：</p><p><img src="https://opensource.com/sites/default/files/uploads/linux-dual-boot_09.png" alt="保留未分配空間的分區" title="Leaving a partition with unallocated space"></p><p>確認分區看起來合理，然後單擊“下一步”。現在將開始安裝 Windows。</p><p><img src="https://opensource.com/sites/default/files/uploads/linux-dual-boot_10.png" alt="安裝 Windows" title="Installing Windows"></p><p>如果你的電腦成功地引導進入了 Windows 桌面環境，你就可以進入下一步了。</p><p><img src="https://opensource.com/sites/default/files/uploads/linux-dual-boot_11.png" alt="Windows 桌面" title="Windows desktop"></p><h4 id="安裝-ubuntu" tabindex="-1">安裝 Ubuntu <a class="header-anchor" href="#安裝-ubuntu" aria-label="Permalink to “安裝 Ubuntu”">​</a></h4><p>無論你是已經安裝了 Windows，還是完成了上面的步驟，現在你已經安裝了 Windows。現在用你之前創建的 Ubuntu 安裝介質來引導進入 Ubuntu。繼續插入安裝介質並從中引導你的電腦，同樣，啓動引導菜單的快捷鍵因計算機型號而異，因此如果你不確定，請查閲你的文檔。如果一切順利的話，當安裝介質加載完成之後，你將會看到以下界面：</p><p><img src="https://opensource.com/sites/default/files/uploads/linux-dual-boot_12.png" alt="Ubuntu 安裝歡迎屏幕" title="Ubuntu installation welcome screen"></p><p>在這裏，你可以選擇 “嘗試 Ubuntu” 或者 “安裝 Ubuntu”。現在不要安裝，相反，點擊 “嘗試 Ubuntu”。當完成加載之後，你應該可以看到 Ubuntu 桌面。</p><p><img src="https://opensource.com/sites/default/files/uploads/linux-dual-boot_13.png" alt="Ubuntu 桌面" title="Ubuntu desktop"></p><p>通過單擊“嘗試 Ubuntu”,你已經選擇在安裝之前試用 Ubuntu。 在 Live 模式下，你可以試用 Ubuntu，確保在你安裝之前一切正常。Ubuntu 能兼容大多數 PC 硬件，但最好提前測試一下。確保你可以訪問互聯網並可以正常播放音頻和視頻。登錄 YouTube 播放視頻是一次性完成所有這些工作的好方法（LCTT 譯註：國情所限，這個方法在這裏並不奏效）。如果你需要連接到無線網絡，請單擊屏幕右上角的網絡圖標。在那裏，你可以找到一個無線網絡列表並連接到你的無線網絡。</p><p>準備好之後，雙擊桌面上的 “安裝 Ubuntu 18.04 LTS” 圖標啓動安裝程序。</p><p>選擇要用於安裝過程的語言，然後單擊 “繼續”。</p><p><img src="https://opensource.com/sites/default/files/uploads/linux-dual-boot_15.png" alt="選擇 Ubuntu 的語言" title="Select language in Ubuntu"></p><p>接下來，選擇鍵盤佈局。完成後選擇後，單擊“繼續”。</p><p><img src="https://opensource.com/sites/default/files/uploads/linux-dual-boot_16.png" alt="選擇 Ubuntu 的鍵盤" title="Select keyboard in Ubuntu"></p><p>在下面的屏幕上有一些選項。你可以選擇一個正常安裝或最小化安裝。對大多數人來説，普通安裝是理想的。高級用户可能想要默認安裝應用程序比較少的最小化安裝。此外，你還可以選擇下載更新以及是否包含第三方軟件和驅動程序。我建議同時檢查這兩個方框。完成後，單擊“繼續”。</p><p><img src="https://opensource.com/sites/default/files/uploads/linux-dual-boot_17.png" alt="選擇 Ubuntu 安裝選項" title="Choose Ubuntu installation options"></p><p>下一個屏幕將詢問你是要擦除磁盤還是設置雙啓動。由於你是雙啓動，因此請選擇“安裝 Ubuntu，與 Windows 10共存”，單擊“現在安裝”。</p><p><img src="https://opensource.com/sites/default/files/uploads/linux-dual-boot_18.png" alt="安裝 Ubuntu，與 Windows 10共存" title="Install Ubuntu alongside Windows"></p><p>可能會出現以下屏幕。如果你從頭開始安裝 Windows 並在磁盤上保留了未分區的空間，Ubuntu 將會自動在空白區域中自行設置分區，因此你將看不到此屏幕。如果你已經安裝了 Windows 10 並且它佔用了整個驅動器，則會出現此屏幕，並在頂部為你提供一個選擇磁盤的選項。如果你只有一個磁盤，則可以選擇從 Windows 竊取多少空間給 Ubuntu。你可以使用鼠標左右拖動中間的垂直線以從其中一個分區中拿走一些空間並給另一個分區，按照你自己想要的方式調整它，然後單擊“現在安裝”。</p><p><img src="https://opensource.com/sites/default/files/uploads/linux-dual-boot_18b.png" alt="分配驅動器空間" title="Allocate drive space"></p><p>你應該會看到一個顯示 Ubuntu 計劃將要做什麼的確認屏幕，如果一切正常，請單擊“繼續”。</p><p><img src="https://opensource.com/sites/default/files/uploads/linux-dual-boot_19.png" alt="確認屏幕" title="Confirmation screen"></p><p>Ubuntu 正在後台安裝。不過，你仍需要進行一些配置。當 Ubuntu 試圖找到你的位置時，你可以點擊地圖來縮小範圍以確保你的時區和其他設置是正確的。</p><p><img src="https://opensource.com/sites/default/files/uploads/linux-dual-boot_20.png" alt="選擇地理位置" title="Select location"></p><p>接下來，填寫用户賬户信息：你的姓名、計算機名、用户名和密碼。完成後單擊“繼續”。</p><p><img src="https://opensource.com/sites/default/files/uploads/linux-dual-boot_21.png" alt="賬户設置" title="Account setup"></p><p>現在你就擁有它了，安裝完成了。繼續並重啓你的電腦。</p><p><img src="https://opensource.com/sites/default/files/uploads/linux-dual-boot_22.png" alt="Ubuntu 安裝完成" title="Installation complete"></p><p>如果一切按計劃進行，你應該會在計算機重新啓動時看到類似的屏幕，選擇 Ubuntu 或 Windows 10，其他選項是用於故障排除，所以我們一般不會選擇進入其中。</p><p><img src="https://opensource.com/sites/default/files/uploads/linux-dual-boot_23.png" alt="選擇操作系統" title="Chose which OS to use"></p><p>嘗試啓動並進入 Ubuntu 或 Windows 以測試是否安裝成功並確保一切按預期地正常工作。如果沒有問題，你已經在你的電腦上安裝了 Windows 和 Ubuntu 。</p><hr>',60)),n("p",null,[t[10]||(t[10]=o("via: ",-1)),i(s,{href:"https://opensource.com/article/18/5/dual-boot-linux"},{default:u(()=>[...t[9]||(t[9]=[o("https://opensource.com/article/18/5/dual-boot-linux",-1)])]),_:1})]),n("p",null,[t[15]||(t[15]=o("作者：",-1)),i(s,{href:"https://opensource.com/users/jlacroix"},{default:u(()=>[...t[11]||(t[11]=[o("Jay LaCroix",-1)])]),_:1}),t[16]||(t[16]=o(" 選題：",-1)),i(s,{href:"https://github.com/lujun9972"},{default:u(()=>[...t[12]||(t[12]=[o("lujun9972",-1)])]),_:1}),t[17]||(t[17]=o(" 譯者：",-1)),i(s,{href:"https://github.com/Auk7F7"},{default:u(()=>[...t[13]||(t[13]=[o("Auk7F7",-1)])]),_:1}),t[18]||(t[18]=o(" 校對：",-1)),i(s,{href:"https://github.com/wxy"},{default:u(()=>[...t[14]||(t[14]=[o("wxy",-1)])]),_:1})]),n("p",null,[t[21]||(t[21]=o("本文由 ",-1)),i(s,{href:"https://github.com/LCTT/TranslateProject"},{default:u(()=>[...t[19]||(t[19]=[o("LCTT",-1)])]),_:1}),t[22]||(t[22]=o(" 原創編譯，",-1)),i(s,{href:"https://linux.cn/"},{default:u(()=>[...t[20]||(t[20]=[o("Linux中國",-1)])]),_:1}),t[23]||(t[23]=o(" 榮譽推出",-1))])])}const c=l(r,[["render",b]]);export{U as __pageData,c as default};
